<?php
 namespace QQWorld\Indexer\Test\Unit\Block\Backend\Grid\Column\Renderer; class ScheduledTest extends \PHPUnit\Framework\TestCase { public function testRender($rowValue, $class, $text) { $html = '<span class="' . $class . '"><span>' . $text . '</span></span>'; $row = new \QQWorld\Framework\DataObject(); $column = new \QQWorld\Framework\DataObject(); $context = $this->getMockBuilder(\QQWorld\Backend\Block\Context::class) ->disableOriginalConstructor() ->getMock(); $model = new \QQWorld\Indexer\Block\Backend\Grid\Column\Renderer\Scheduled($context); $column->setGetter('getValue'); $row->setValue($rowValue); $model->setColumn($column); $result = $model->render($row); $this->assertEquals($result, $html); } public function typeProvider() { return [ [true, 'grid-severity-notice', __('Update by Schedule')], [false, 'grid-severity-major', __('Update on Save')], ['', 'grid-severity-major', __('Update on Save')], ]; } } 